const config = document.querySelector("#app").dataset;
function Entete({ nom }) { return <h1 id="club">{nom}</h1>; }
function Carte({ atelier }) { return <article id="carte"><h2 id="titre">{atelier.titre}</h2><p id="ville">{atelier.ville}</p><p id="places">{atelier.places} places</p></article>; }
function App() {
  const atelier = { titre: config.titre, ville: config.ville, places: Number(config.places) };
  return <main><Entete nom={config.club} /><Carte atelier={atelier} /></main>;
}
root.render(<App />);

